    init { check(marks.size == 300) { "A lista de Marcas Lunares deve conter exatamente 300 entradas." } }

    internal fun todas(): List<Mark> = marks

    fun sortear(random: Random = Random.Default): Mark = marks.random(random)

    fun sortearCoerente(
        formaEspiritual: SpiritualFormService.Animal,
        locale: Locale = Locale.getDefault(),
        random: Random = Random.Default
    ): Mark = LunarMarkCoherenceService.sortear(formaEspiritual, random)

    fun sortearExibicaoCoerente(
        formaEspiritual: SpiritualFormService.Animal,
        locale: Locale = Locale.getDefault(),
        random: Random = Random.Default
    ): String {
        val mark = sortearCoerente(formaEspiritual, locale, random)
        return if (locale.language.equals("en", ignoreCase = true)) mark.english else mark.portuguese
    }


    fun sortearExibicao(locale: Locale = Locale.getDefault(), random: Random = Random.Default): String {
        val mark = sortear(random)
        return if (locale.language.equals("en", ignoreCase = true)) mark.english else mark.portuguese
    }

    fun size(): Int = marks.size
}
